#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

# Run from the repo root so .env lands there, whatever the caller's cwd.
cd "$(git rev-parse --show-toplevel)"

# gh can't infer the repo from an SSH host alias like "github-private", so pin it.
GH_REPO=$(git remote get-url origin | sed -E 's#^.*[:/]([^/:]+/[^/]+)$#\1#; s#\.git$##')
export GH_REPO
WORKFLOW_FILE="publish-chrome-extension.yml"
CWS_SCOPE="https://www.googleapis.com/auth/chromewebstore"
PLAYGROUND_URL="https://developers.google.com/oauthplayground"

gh_is_admin() {
  [[ "$(gh api "repos/$GH_REPO" --jq .permissions.admin 2>/dev/null)" == "true" ]]
}

# Prefer the active gh account; fall back to the repo owner's logged-in account
# via GH_TOKEN, so the global active account is left untouched.
connect_github() {
  unset GH_TOKEN
  gh_is_admin && return 0
  local token
  token=$(gh auth token --user "${GH_REPO%%/*}" 2>/dev/null) || return 1
  GH_TOKEN="$token" gh_is_admin || return 1
  export GH_TOKEN="$token"
}

# ask_until KEY "Prompt" REGEX "hint" [secret] re-asks until the value matches.
ask_until() {
  local key="$1" prompt="$2" regex="$3" hint="$4" secret="${5:-}"
  while true; do
    if [[ -n "$secret" ]]; then ask_secret "$key" "$prompt"; else ask "$key" "$prompt"; fi
    [[ "${!key}" =~ $regex ]] && return 0
    warn "$hint"
  done
}

# Prints the OAuth error, never the access token.
verify_refresh_token() {
  local response
  response=$(curl -sS https://oauth2.googleapis.com/token \
    --data-urlencode "client_id=$CHROME_EXTENSION_CLIENT_ID" \
    --data-urlencode "client_secret=$CHROME_EXTENSION_CLIENT_SECRET" \
    --data-urlencode "refresh_token=$CHROME_EXTENSION_REFRESH_TOKEN" \
    --data-urlencode "grant_type=refresh_token" 2>&1) || true
  if [[ "$response" == *'"access_token"'* ]]; then
    if [[ "$response" == *"$CWS_SCOPE"* ]]; then return 0; fi
    warn "The token works but lacks the $CWS_SCOPE scope."
    return 1
  fi
  local details
  details=$(printf '%s' "$response" | grep -E '"error(_description)?"' | tr -s ' \n' ' ' || true)
  warn "Google rejected the credentials:"
  note "${details:-$response}"
  return 1
}

# Builds the consent URL for OUR client, so the Playground's default client
# (407408718192…) can never end up issuing the token.
auth_url() {
  printf '%s?client_id=%s&redirect_uri=%s&response_type=code&scope=%s&access_type=offline&prompt=consent' \
    "https://accounts.google.com/o/oauth2/v2/auth" "$CHROME_EXTENSION_CLIENT_ID" \
    "https%3A%2F%2Fdevelopers.google.com%2Foauthplayground" \
    "https%3A%2F%2Fwww.googleapis.com%2Fauth%2Fchromewebstore"
}

# code_from_url URL prints the URL-decoded ?code= value (or the input if it's a bare code).
code_from_url() {
  local code="$1"
  [[ "$code" == *code=* ]] && { code="${code#*code=}"; code="${code%%&*}"; }
  code="${code//+/ }"
  printf '%b' "${code//%/\\x}"
}

# Opens consent for our client, exchanges the pasted code, saves the refresh token.
obtain_refresh_token() {
  local response code
  while true; do
    open_url "$(auth_url)"
    step "Sign in with the Google account that owns the store listing."
    note "    On 'Google hasn't verified this app': Advanced → Go to … (unsafe) → Continue."
    note "    On 'Access blocked: … has not completed the Google verification process':"
    note "    the app is still in Testing. Publish it here, then retry:"
    note "    https://console.cloud.google.com/auth/audience?project=$GCP_PROJECT_ID"
    step "You land on the OAuth Playground with ?code=… in the address bar."
    step "Don't click anything there: copy the whole address-bar URL."
    note "    (Codes expire in ~10 minutes and work once.)"
    ask AUTH_REDIRECT_URL "Paste the URL:" || return 1
    code=$(code_from_url "$AUTH_REDIRECT_URL")
    response=$(curl -sS https://oauth2.googleapis.com/token \
      --data-urlencode "client_id=$CHROME_EXTENSION_CLIENT_ID" \
      --data-urlencode "client_secret=$CHROME_EXTENSION_CLIENT_SECRET" \
      --data-urlencode "code=$code" \
      --data-urlencode "redirect_uri=$PLAYGROUND_URL" \
      --data-urlencode "grant_type=authorization_code" 2>&1) || true
    CHROME_EXTENSION_REFRESH_TOKEN=$(printf '%s' "$response" | sed -nE 's/.*"refresh_token" *: *"([^"]+)".*/\1/p' | head -n1)
    if [[ -n "$CHROME_EXTENSION_REFRESH_TOKEN" ]]; then
      write_env CHROME_EXTENSION_REFRESH_TOKEN "$CHROME_EXTENSION_REFRESH_TOKEN"
      if [[ "$response" == *refresh_token_expires_in* ]]; then
        warn "Google says this token expires in 7 days: the consent screen is still"
        warn "in 'Testing'. Audience → 'Publish app', then redo this stage."
        confirm "Redo it now?" && continue
      fi
      return 0
    fi
    warn "Google didn't return a refresh token:"
    note "$(printf '%s' "$response" | grep -E '"error(_description)?"' | tr -s ' \n' ' ' || printf '%s' "$response")"
    confirm "Try again?" || return 1
  done
}

banner "Chrome Web Store publishing for $GH_REPO"

# ──────────────────────────────────────────────────────────────────────────
stage "GitHub access"
say "The publish workflow reads 4 repository secrets. Setting them needs a gh"
say "account with admin rights on $GH_REPO."
if ! command -v gh >/dev/null 2>&1; then
  warn "gh isn't installed: secrets will be listed at the end for you to set by hand."
  pause
else
  until connect_github; do
    warn "No logged-in gh account has admin rights on $GH_REPO."
    step "In another terminal run: gh auth login   (sign in as ${GH_REPO%%/*})"
    if ! confirm "Done, check again?"; then
      warn "Continuing without GitHub: secrets will be listed at the end."
      break
    fi
  done
  if gh_is_admin; then
    say "${GREEN}✓${RESET} gh can manage secrets on $GH_REPO."
    existing_secrets=$(gh secret list --json name,updatedAt --jq '.[] | select(.name | startswith("CHROME_EXTENSION_")) | "\(.name) (updated \(.updatedAt[:10]))"' 2>/dev/null || true)
    if [[ -n "$existing_secrets" ]]; then
      note "Already set (you'll be asked before they're replaced):"
      while IFS= read -r line; do note "  - $line"; done <<<"$existing_secrets"
    fi
  fi
  pause
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Chrome Web Store item"
say "The API can only update an extension that already exists in the store."
note "Your publisher Google account also needs 2-Step Verification:"
note "https://myaccount.google.com/signinoptions/twosv"
open_url "https://chrome.google.com/webstore/devconsole/"
if ! confirm "Is GitHub Tabs already listed in the Developer Dashboard?"; then
  if confirm "Build dist/github-tabs.zip for the first upload now?"; then
    npm run build:bundle
  fi
  step "Click '+ New item' and upload dist/github-tabs.zip."
  step "Fill in the 'Store listing' and 'Privacy' tabs (PRIVACY.md has the policy text)."
  step "Click 'Submit for review'. Later versions will come from CI."
  pause "Press Enter once the item exists"
fi
step "Open the GitHub Tabs item. Its 32-letter ID is on the 'Package' tab"
step "(it's also the ID shown for the extension on chrome://extensions)."
ask_until CHROME_EXTENSION_ID "Paste the extension ID:" '^[a-p]{32}$' \
  "That doesn't look like an extension ID (32 letters a–p)."
write_env CHROME_EXTENSION_ID "$CHROME_EXTENSION_ID"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Google Cloud project + Chrome Web Store API"
say "The OAuth client lives in a Google Cloud project. Reuse one if you set this up before."
open_url "https://console.cloud.google.com/projectselector2/home/dashboard"
step "Pick an existing project or click 'Create project' (any name works)."
step "Copy the Project ID (not the name) from the dashboard's 'Project info' card."
ask_until GCP_PROJECT_ID "Paste the project ID:" '^[a-z][a-z0-9-]{4,28}[a-z0-9]$' \
  "Project IDs are 6–30 chars: lowercase letters, digits and hyphens."
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
open_url "https://console.cloud.google.com/apis/library/chromewebstore.googleapis.com?project=$GCP_PROJECT_ID"
step "Click 'Enable' (if it says 'Manage', it's already enabled)."
pause "Press Enter once the Chrome Web Store API is enabled"

# ──────────────────────────────────────────────────────────────────────────
stage "OAuth consent screen"
open_url "https://console.cloud.google.com/auth/overview?project=$GCP_PROJECT_ID"
say "If it shows 'Google Auth Platform not configured yet', click 'Get started':"
step "App information: any app name (e.g. 'GitHub Tabs CI') + your email as support email."
step "Audience: choose 'External'."
step "Contact information: your email. Accept the policy, then 'Create'."
say "Then, in the left menu, open 'Audience':"
step "Under 'Publishing status' click 'Publish app' and confirm ('In production')."
warn "Skip this and Google expires the refresh token after 7 days, breaking CI."
note "No verification is needed for your own account: you'll just click through"
note "an 'unverified app' warning once when authorizing."
pause "Press Enter once the app is In production"

# ──────────────────────────────────────────────────────────────────────────
stage "OAuth client"
open_url "https://console.cloud.google.com/auth/clients?project=$GCP_PROJECT_ID"
step "Click 'Create client'. Application type: 'Web application'. Any name."
step "Under 'Authorized redirect URIs' click 'Add URI' and enter:"
note "    $PLAYGROUND_URL"
step "Click 'Create'. The dialog shows the Client ID and Client secret."
warn "Google shows the secret only now: copy it (or 'Download JSON') before closing."
note "Reusing an old client without its secret? Open the client and use 'Add secret'."
ask_until CHROME_EXTENSION_CLIENT_ID "Paste the Client ID:" '^[0-9]+-[a-z0-9]+\.apps\.googleusercontent\.com$' \
  "Client IDs end in .apps.googleusercontent.com."
ask_until CHROME_EXTENSION_CLIENT_SECRET "Paste the Client secret (hidden):" '^[A-Za-z0-9_-]{20,}$' \
  "That doesn't look like a client secret (usually starts GOCSPX-)." secret
write_env CHROME_EXTENSION_CLIENT_ID "$CHROME_EXTENSION_CLIENT_ID"
write_env CHROME_EXTENSION_CLIENT_SECRET "$CHROME_EXTENSION_CLIENT_SECRET"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Refresh token"
say "You approve access in the browser; the wizard swaps the code for a refresh token."
if ! obtain_refresh_token; then
  SKIPPED+=("refresh token: re-run this wizard")
  warn "No refresh token yet: the next stage will fail."
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Verify the credentials"
say "Exchanging the refresh token for an access token, exactly as CI will…"
credentials_ok=false
while true; do
  if verify_refresh_token; then
    credentials_ok=true
    say "${GREEN}✓${RESET} Google issued an access token with the Chrome Web Store scope."
    break
  fi
  note "invalid_client → wrong Client ID/secret. unauthorized_client → token issued"
  note "for a different client. invalid_grant → token revoked or expired."
  confirm "Re-enter the client secret and get a fresh refresh token?" || break
  ask_secret CHROME_EXTENSION_CLIENT_SECRET "Client secret (hidden):"
  write_env CHROME_EXTENSION_CLIENT_SECRET "$CHROME_EXTENSION_CLIENT_SECRET"
  obtain_refresh_token || true
done
note "The extension ID can't be checked here: the first CI run confirms it."
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Save GitHub repository secrets"
say "These four secrets go together: the refresh token is tied to this client."
note "Target: https://github.com/$GH_REPO/settings/secrets/actions"
$credentials_ok || warn "The credentials did NOT verify: CI will fail with them."
if confirm "Write all four CHROME_EXTENSION_* secrets (replacing any existing ones)?"; then
  set_secret CHROME_EXTENSION_ID "$CHROME_EXTENSION_ID"
  set_secret CHROME_EXTENSION_CLIENT_ID "$CHROME_EXTENSION_CLIENT_ID"
  set_secret CHROME_EXTENSION_CLIENT_SECRET "$CHROME_EXTENSION_CLIENT_SECRET"
  set_secret CHROME_EXTENSION_REFRESH_TOKEN "$CHROME_EXTENSION_REFRESH_TOKEN"
else
  SKIPPED+=("GitHub secrets CHROME_EXTENSION_* (values are in $ENV_FILE)")
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "First publish"
say "The workflow tests, packages and uploads a new version, then submits it for"
say "public review. From now on it runs on every push to main touching shipped files."
if confirm "Run the publish workflow on main now?"; then
  if gh workflow run "$WORKFLOW_FILE" --ref main >/dev/null 2>&1; then
    say "${GREEN}✓${RESET} Workflow triggered."
    sleep 3
    open_url "https://github.com/$GH_REPO/actions/workflows/$WORKFLOW_FILE"
    step "Watch the 'Publish to Chrome Web Store' step go green."
  else
    SKIPPED+=("trigger the publish workflow: gh workflow run $WORKFLOW_FILE --ref main")
    warn "Couldn't trigger the workflow; run it from the Actions tab instead."
  fi
else
  note "Later: gh workflow run $WORKFLOW_FILE --ref main  (or Actions → Run workflow)"
fi
pause

finish
note "Values are saved in $ENV_FILE (gitignored), so re-runs only need Enter."
note "Delete it once CI publishes successfully if you'd rather not keep them locally."
printf '\n'
}

run_wizard "$@"; exit
